/**
 * Vendored `tabbable@6.5.0` UMD build (dist/index.umd.min.js), base64-encoded.
 *
 * The tab-order tool must run tabbable inside the page, and the MCP ships as a
 * self-contained tarball built with plain tsc (no bundler), so the library is
 * embedded here rather than resolved at runtime. When tabbable is upgraded,
 * regenerate this file from node_modules and bump the pin.
 *
 * Injected with page.addScriptTag({content}); the UMD exposes the namespace at
 * window.tabbable, so call window.tabbable.tabbable(...).
 */

export const TABBABLE_UMD = Buffer.from(
  '',
  'base64',
).toString('utf8');
